import { describe, it, expect } from "vitest";
import { processScenario } from "./claim-office.js";

// Unless stated otherwise: newcomer customer (0 years), first quote in scenario,
// so premium = (base + item surcharges + 10 % first insurance of base) + 5 G fee.

describe("Claim Office — quote", () => {
  describe("edge cases", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
  });

  describe("main item base premiums", () => {
    it.todo("sword (base 100) → premium 115 G");
    it.todo("amulet (base 60) → premium 71 G");
    it.todo("staff (base 80) → premium 93 G");
    it.todo("potion (base 40) → premium 49 G");
  });

  describe("components and building blocks", () => {
    it.todo("2 runes (base 50) → premium 60 G");
    it.todo("3 runes (block, base 60) → premium 71 G");
    it.todo("4 runes (no block, base 100) → premium 115 G");
    it.todo("7 runes (base 175 → 197.5 G) → premium 198 G (rounded up in MHPCO's favor)");
    it.todo("2 runes + 1 moonstone (no block: different types, base 75 → 87.5) → premium 88 G");
    it.todo("3 runes + 3 moonstones (two separate blocks, base 120) → premium 137 G");
  });

  describe("item-specific modifiers", () => {
    it.todo("cursed sword (steel, enchantment 3) → premium 165 G");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies → premium 145 G");
    it.todo("cursed sword with enchantment 5 → both surcharges apply → premium 195 G");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge → premium 115 G");
    it.todo("cursed sword with enchantment 4 → only curse surcharge → premium 165 G");
    it.todo("cursed sword + plain amulet → curse surcharge only on sword's base (210 before policy modifiers) → premium 231 G");
  });

  describe("policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years → loyalty discount applies → sword premium 95 G");
    it.todo("customer with 1 year → no loyalty discount → sword premium 115 G");
    it.todo("second quote in scenario gets 15 % follow-up discount → sword premium 100 G");
    it.todo("long-standing customer's second contract, cursed sword enchantment 7 → premium 160 G (first insurance still applies)");
  });

  describe("errors", () => {
    it.todo("quote with unknown item type (broomstick) → throws");
  });
});

describe("Claim Office — claim", () => {
  describe("standard reimbursement", () => {
    it.todo("regular steel sword enchantment 3, damage 500 → payout 400, remainingCap 1600");
    it.todo("rune, damage 200 → payout 100, remainingCap 400");
  });

  describe("enchantment threshold vs. dragon material", () => {
    it.todo("dragon-material sword enchantment 5, damage 800 → payout 700");
    it.todo("steel sword enchantment 9, damage 1000 → payout 400 (50 % then deductible)");
    it.todo("dragon-material sword enchantment 9, damage 1000 → payout 400 (50 % rule wins)");
    it.todo("dragon-material sword exactly enchantment 8, damage 1000 → payout 400");
    it.todo("payout of 350.5 (enchantment 8 sword, damage 901) → payout 350 (rounded down)");
  });

  describe("deductible per damage event", () => {
    it.todo("dragon attack damages sword (500) and amulet (300) → payout 600, remainingCap 2600");
    it.todo("two insured swords both damaged (500 each) → each with own deductible → payout 800, remainingCap 3200");
  });

  describe("cap", () => {
    it.todo("cursed sword cap is based on insurance value: damage 1500 → payout 1400, remainingCap 600");
    it.todo("sword + 3 runes insurance sum 1750 (cap 3500): sword damage 500 → payout 400, remainingCap 3100");
    it.todo("two successive claims of 1500 on a sword → payouts 1400 then 600, remainingCap 600 then 0");
  });

  describe("errors", () => {
    it.todo("damage to an item type not in the policy (amulet when only sword insured) → throws");
    it.todo("damage to an unknown item type → throws");
    it.todo("more damage entries of a type than insured (two swords damaged, one insured) → throws");
    it.todo("damage with negative amount (-200) → throws");
  });
});

describe("Claim Office — CLI", () => {
  it.todo("schema example (5-year customer, silver amulet quote, fire claim 200) → {results:[{premium:59},{payout:100,remainingCap:1100}]}");
  it.todo("quote with unknown item type → non-zero exit, error on stderr, nothing on stdout");
  it.todo("claim with negative amount → non-zero exit, error on stderr");
});

