const RUNE_BLOCK_SIZE = 3;
const RUNE_BLOCK_BASE_PREMIUM = 60;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

// Integer arithmetic first, then divide: keeps results exact (100 * 1.1 !== 110).
const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;

// Only the final premium is rounded; intermediate amounts stay exact.
const roundInMHPCOsFavor = (amount: number): number => Math.ceil(amount);

const formsRuneBlock = (items: QuoteItem[]): boolean =>
  items.filter((item) => item.type === "rune").length === RUNE_BLOCK_SIZE;

const sumOfItemBasePremiums = (items: QuoteItem[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const totalBasePremium = (items: QuoteItem[]): number =>
  formsRuneBlock(items) ? RUNE_BLOCK_BASE_PREMIUM : sumOfItemBasePremiums(items);

const quotePremium = (items: QuoteItem[]): number => {
  const basePremium = totalBasePremium(items);
  const surcharge = percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
  const exactPremium = basePremium + surcharge + PROCESSING_FEE;
  return roundInMHPCOsFavor(exactPremium);
};

