const INSURANCE_VALUES: Record<string, number> = { sword: 1000, rune: 250 };
// A policy covers claims up to this multiple of its items' total insurance value.
const COVERAGE_CAP_MULTIPLIER = 2;
const DEDUCTIBLE = 100;
const damagePayout = (damage: Damage): number => damage.amount - DEDUCTIBLE;

// A claim's policy is referenced by the index of the quote step that created it.
const processClaim = (step: ClaimStep, steps: Step[]) => {
  const policy = steps[step.policy] as QuoteStep;
  const payout = sumOf(step.incident.damages, damagePayout);
  return { payout, remainingCap: coverageCap(policy.items) - payout };
};

// Dispatches each step to its handler by op.
const processStep = (step: Step, scenario: Scenario, stepIndex: number) => {
  switch (step.op) {
    case "quote":
      return processQuote(step, scenario.customer, stepIndex);
    case "claim":
      return processClaim(step, scenario.steps);
  }
};

export const processScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step, stepIndex) => processStep(step, scenario, stepIndex)),
});

